      "strat_rejection_rsd_thought0_step0": "Hais tias, 'Qhov no yog RSD. Kev mob siab muaj tiag, tab sis lub ntsiab lus tej zaum tsis muaj tseeb.'",
      "strat_rejection_rsd_thought0_step1": "Paub tias nws yog RSD txo tau kev mob siab",
      "strat_rejection_rsd_thought0_step2": "Hais dua",
      "strat_rejection_rsd_thought1_name": "Tos 24 Teev",
      "strat_rejection_rsd_thought1_step0": "Tsis xa ntawv, tsis tso tawm, tsis txiav txim siab rau 24 teev",
      "strat_rejection_rsd_thought1_step1": "RSD nce sai thiab poob sai",
      "strat_rejection_rsd_thought1_step2": "Tos",
      "strat_rejection_rsd_thought2_name": "Lwm Cov Lus Piav Qhia",
      "strat_rejection_rsd_thought2_step0": "Sau 3 lwm yam laj thawj uas tej zaum tshwm sim",
      "strat_rejection_rsd_thought2_step1": "Xaiv qhov uas siab zoo tshaj thiab muaj tseeb tau",
      "strat_rejection_rsd_thought2_step2": "Tuav maj mam",
      "strat_rejection_rsd_thought3_name": "Txheeb Xyuas Qhov Tseeb",
      "strat_rejection_rsd_thought3_step0": "Nug ib tug neeg uas koj ntseeg tias, 'Kuv puas nkag siab qhov no yog?'",
      "strat_rejection_rsd_thought3_step1": "Txais cov lus teb ncaj ncees",
      "strat_rejection_rsd_thought3_step2": "Kho txoj kev xav",
      "strat_rejection_rsd_thought4_name": "Qhov No Yuav Dhau Hauv 2 Teev",
      "strat_rejection_rsd_thought4_step0": "Nco qab: RSD feem ntau nce siab thiab poob hauv 1-3 teev",
      "strat_rejection_rsd_thought4_step1": "Koj twb hla dhau yav tas los lawm",
      "strat_rejection_rsd_thought4_step2": "Tos",
      "strat_rejection_rsd_whenItPersists": "RSD kho tau thiab tsis yog koj qhov txhaum; mus ntsib kws kho mob lub hlwb lossis kws kho siab paub txog ADHD.",
      "strat_sadness_high_body0_dur": "2 feeb",
      "strat_sadness_high_body0_name": "Tuav Lub Nab Kuab",
      "strat_sadness_high_body0_step0": "Tuav ib lub nab kuab hauv koj txhais tes 30-60 vib nas this",
      "strat_sadness_high_body0_step1": "Xav txog qhov txias",
      "strat_sadness_high_body0_step2": "Hloov lwm txhais tes",
      "strat_sadness_high_body0_why": "Kev hnov muaj zog rub lub siab tawm ntawm kev xav ncig thaum kev tu siab hnyav dhau.",
      "strat_sadness_high_body1_dur": "2 feeb",
      "strat_sadness_high_body1_name": "Ntaus Ob Sab Xub Pwg",
      "strat_sadness_high_body1_step0": "Muab npab sib tshuam saum hauv siab",
      "strat_sadness_high_body1_step1": "Ntaus ob sab xub pwg hloov qeeb 2 feeb",
