      "run_ev_at": "{value1}. {value2} at {value3} in.",
      "run_ev_ctwd_long": "Stickout drifts long",
      "run_ev_ctwd_short": "Stickout gets short",
      "run_ev_gap": "Fit-up gap",
      "run_ev_heat": "Heat build-up",
      "run_ev_step": "Plate thins to 1/8 in.",
